<template>
  <section class="docs-shell"><header><div><small>CHART RECORDS</small><h2>Documents</h2><p>Filed clinical, administrative and continuity records.</p></div><v-btn v-if="canFile" x-small depressed color="#0f766e" dark @click="$emit('file-document')"><v-icon x-small left>mdi-file-plus-outline</v-icon>File document</v-btn></header>
    <div class="toolbar"><v-text-field v-model="search" prepend-inner-icon="mdi-magnify" label="Search documents" dense outlined hide-details/><v-select v-model="category" :items="categories" label="Category" dense outlined hide-details/></div>
    <div class="docs-layout"><div class="docs-list"><button v-for="doc in filtered" :key="doc.id" :class="{active:selectedId===doc.id}" @click="selectedId=doc.id"><v-icon small>mdi-file-document-outline</v-icon><span><strong>{{ doc.title||'Document' }}</strong><small>{{ doc.category||'Clinical document' }} · {{ format(doc.createdAt) }}</small></span><em>{{ doc.status||'Filed' }}</em></button><p v-if="!filtered.length" class="empty">No matching document.</p></div>
      <article class="doc-detail" v-if="selected"><header><div><small>{{ selected.category||'DOCUMENT' }}</small><h3>{{ selected.title }}</h3></div><span>{{ selected.status||'Filed' }}</span></header><p>{{ selected.content||'No text content stored.' }}</p><footer>Filed {{ format(selected.createdAt) }} by {{ selected.createdBy||'Clinical user' }}</footer></article><div v-else class="doc-detail empty">Select a document to review.</div></div>
  </section>
</template>
<script>
export default {name:'Patient360DocumentsTab',props:{documents:{type:Array,default:()=>[]},role:{type:String,default:''},readOnly:Boolean},data:()=>({search:'',category:'All',selectedId:''}),computed:{canFile(){return !this.readOnly&&['ADMIN','DOCTOR','NP','NURSE','MIDWIFE','RECORDS','FRONT_DESK'].includes(this.role)},categories(){return ['All',...new Set(this.documents.map(x=>x.category||'Clinical document'))]},filtered(){const q=this.search.toLowerCase();return this.documents.filter(x=>(this.category==='All'||(x.category||'Clinical document')===this.category)&&`${x.title} ${x.category} ${x.content}`.toLowerCase().includes(q))},selected(){return this.documents.find(x=>x.id===this.selectedId)||this.filtered[0]||null}},methods:{format(v){return v?new Date(v).toLocaleString():'-'}}}
</script>
<style scoped>
.docs-shell{padding:14px;background:#f8fbfb;min-height:100%}.docs-shell>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f766e;padding-bottom:10px}.docs-shell small{font-weight:900;color:#64748b}.docs-shell h2{font-size:18px;margin:2px 0}.docs-shell p{margin:0;font-size:12px}.toolbar{display:grid;grid-template-columns:2fr 1fr;gap:8px;margin:10px 0}.docs-layout{display:grid;grid-template-columns:minmax(280px,.85fr) 1.4fr;border:1px solid #cbd5e1;background:white;min-height:340px}.docs-list{border-right:1px solid #cbd5e1}.docs-list button{width:100%;display:grid;grid-template-columns:25px 1fr auto;gap:7px;text-align:left;padding:9px;border-bottom:1px solid #e2e8f0}.docs-list button.active{background:#e7f3f1;border-left:3px solid #0f766e}.docs-list span{display:flex;flex-direction:column}.docs-list small,.docs-list em{font-size:11px;color:#64748b}.doc-detail{padding:16px}.doc-detail header{display:flex;justify-content:space-between}.doc-detail h3{font-size:16px}.doc-detail p{white-space:pre-wrap;margin-top:18px}.doc-detail footer{border-top:1px solid #e2e8f0;padding-top:10px;font-size:11px;color:#64748b}.empty{padding:20px;color:#64748b}@media(max-width:700px){.docs-layout{grid-template-columns:1fr}.docs-list{border-right:0}.toolbar{grid-template-columns:1fr}}
</style>
